window.kbPageData["views/entry/k-1d5df4f144112e04"] = {"key":"entry/k-1d5df4f144112e04","state":{"route":"entry/k-1d5df4f144112e04"},"node":{"id":"k-1d5df4f144112e04","mode":"k","title":"习近平生态文明思想","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["生态文明思想"],"qs":["江苏 2024 C类 行测#2"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["ecology"],"主类":["事实与事件"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"新时代中国特色社会主义生态文明思想是在不断深化对生态文明建设规律认识的过程中形成的，为新时代生态文明建设提供科学理论指导。","review":{"definition":"新时代中国特色社会主义生态文明思想是在不断深化对生态文明建设规律认识的过程中形成的，为新时代生态文明建设提供科学理论指导。","explanation":"2023年7月全国生态环境保护大会讲话将这一思想的形成概括为由实践探索到科学理论指导的重大转变。①对应的是这一已经取得的理论成果，因此入选。","references":[],"evidence":"形成了新时代中国特色社会主义生态文明思想","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"49e1ee3f5a2cb325","label":"生态文明思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.十个坚持\n2022 年 8 月 18 日，习近平生态文明思想研究中心在人民日报刊文，将习近平生态文\n明思想的基本内容概括为“十个坚持”。即：\n（1）坚持党对生态文明建设的全面领导，（2）\n坚持生态兴则文明兴，\n（3）坚持人与自然和谐共生，\n（4）坚持绿水青山就是金山银山，\n（5）\n坚持良好生态环境是最普惠的民生福祉，（6）坚持绿色发展是发展观的深刻革命，（7）坚\n持统筹山水林田湖草沙系统治理，（8）坚持用最严格制度最严密法治保护生态环境，（9）\n坚持把建设美丽中国转化为全体人民自觉行动，\n（10）坚持共谋全球生态文明建设之路。\n（粉\n笔敲黑板：2005 年，时任浙江省委书记习近平同志来到安吉余村考察调研，首次提出“绿\n水青山就是金山银山”科学论断。2025 年是两山理念提出的 20 周年。）\n2.四个重大转变与五个重大关系\n2023 年 7 月 17 日至 18 日，习近平总书记在全国生态环境保护大会上全面总结新时代\n生态文明建设实现“四个重大转变”的历史性成就，深刻阐述新征程上推进生态文明建设需\n要处理好的“五个重大关系”。\n“四个重大转变”即：（1）实现由重点整治到系统治理的重大转变，（2）实现由被动\n应对到主动作为的重大转变，（3）实现由全球环境治理参与者到引领者的重大转变，（4）\n实现由实践探索到科学理论指导的重大转变。\n“五个重大关系”即：（1）高质量发展和高水平保护的关系，（2）重点攻坚和协同治\n理的关系，\n（3）自然恢复和人工修复的关系，\n（4）外部约束和内生动力的关系，\n（5）\n“双碳”\n承诺和自主行动的关系。","source":{"doc":"3ccc56f4000d1642c2d1","first":22,"last":23,"page":22,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"江苏 2024 C类 行测#2":{"paper":"江苏 2024 C类 行测","n":2,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",1],"card":"d3565c6ae694ba8d80961da3","links":[{"id":"k-1d5df4f144112e04","role":"直接考查","why":"形成新时代中国特色社会主义生态文明思想体现了生态文明建设由实践探索转向科学理论指导。"}]}},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-1d5df4f144112e04":[["江苏 2024 C类 行测#2"]]}};
